code.SafeMath.div(uint256,uint256):
function div(uint256 a, uint256 b) internal pure returns (uint256) {
 uint256 c = a / b;
 return c;
 }

code.SafeMath.sub(uint256,uint256):
function sub(uint256 a, uint256 b) internal pure returns (uint256) {
 assert(b <= a);
 return a - b;
 }

code.SafeMath.mul(uint256,uint256):
function mul(uint256 a, uint256 b) internal pure returns (uint256) {
 if (a == 0) {
 return 0;
 }
 uint256 c = a * b;
 assert(c / a == b);
 return c;
 }

code.SafeMath.add(uint256,uint256):
function add(uint256 a, uint256 b) internal pure returns (uint256) {
 uint256 c = a + b;
 assert(c >= a);
 return c;
 }

code.ChristmasClub.getBalance():
function getBalance () public view returns (uint) {
 return balances[msg.sender];
 }

code.ChristmasClub.withdraw():
function withdraw () public {
 uint toWithdraw = balances[msg.sender];
 if (now < withdrawalTime) {
 toWithdraw = toWithdraw.mul(100 - earlyWithdrawalFeePct).div(100);
 balances[owner] = balances[owner].add(balances[msg.sender] - toWithdraw);
 }
 balances[msg.sender] = 0;
 msg.sender.transfer(toWithdraw);
 }

code.ChristmasClub.deposit():
function deposit () public payable {
 balances[msg.sender] = balances[msg.sender].add(msg.value);
 }

code.Ownable.transferOwnership(address):
function transferOwnership(address newOwner) public onlyOwner {
 require(newOwner != address(0));
 OwnershipTransferred(owner, newOwner);
 owner = newOwner;
 }
